pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint256 amount, address nonOwner) public {
        vm.assume(nonOwner != address(0) && nonOwner != address(this));
        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        (bool success,) = address(c).call{value: amount}(abi.encodeWithSignature("sendTo(address,uint256)", nonOwner, amount));
        assertTrue(!success);
    }
}
